SELECT 'датчик написанных проверок ' || fact_gap($1, 'written-tc') || ': «написана» здесь значит «не знаем», а не «нет»' AS detail WHERE NOT fact_fresh($1, 'written-tc') UNION ALL SELECT tc.task_id || ' закрыта, а ' || tc.check_id || ' не написана' FROM project_task_check tc JOIN project_plan_tasks t ON t.project_id = tc.project_id AND t.id = tc.task_id AND t.state = 'closed' WHERE tc.project_id = $1 AND tc.said_as = 'доказательство' AND EXISTS (SELECT 1 FROM project_written_check WHERE project_id = $1) AND NOT EXISTS (SELECT 1 FROM project_written_check w WHERE w.project_id = tc.project_id AND w.check_id = tc.check_id) AND true ORDER BY 1
